'use server'

export type RecipeState = {
  errors?: { name?: string; minutes?: string }
  message?: string
}

export async function createRecipe(prev: RecipeState, formData: FormData): Promise<RecipeState> {
  const name = String(formData.get('name') ?? '').trim()
  const minutes = Number(formData.get('minutes'))
  const errors: NonNullable<RecipeState['errors']> = {}

  if (name.length < 3) errors.name = 'Nom kamida 3 ta belgidan iborat bo\'lsin'
  if (!Number.isInteger(minutes) || minutes <= 0) errors.minutes = 'Vaqt musbat butun son bo\'lsin'
  if (Object.keys(errors).length > 0) return { errors }

  return { message: `"${name}" retsepti saqlandi` }
}

