import { useEffect, useState } from 'react'

export function LivePrices() {
  const [prices, setPrices] = useState<number[]>([])
  const [, setBoom] = useState()

  useEffect(() => {
    fetch('/api/prices')
      .then((res) => {
        if (!res.ok) throw new Error('Narxlarni olib bo\'lmadi')
        return res.json() as Promise<number[]>
      })
      .then(setPrices)
      .catch((error) => {
        // setState ichida tashlash — keyingi renderda xato boundary'ga yetadi
        setBoom(() => {
          throw error
        })
      })
  }, [])

  return <ul>{prices.map((p, i) => <li key={i}>{p} so'm</li>)}</ul>
}

