import { NextResponse } from "next/server"
import type { NextRequest } from "next/server"
import { redirectMap } from "@/lib/redirect-map"

export function proxy(request: NextRequest) {
  const entry = redirectMap[request.nextUrl.pathname]
  if (!entry) return NextResponse.next()

  const status = entry.permanent ? 308 : 307
  return NextResponse.redirect(new URL(entry.destination, request.url), status)
}

// fayl: proxy.ts
import { NextResponse } from "next/server"
import type { NextRequest } from "next/server"
import { ScalableBloomFilter } from "bloom-filters"
import generated from "./redirects/bloom-filter.json"

const bloomFilter = ScalableBloomFilter.fromJSON(generated as any)

export async function proxy(request: NextRequest) {
  const pathname = request.nextUrl.pathname

  if (bloomFilter.has(pathname)) {
    const api = new URL(`/api/redirects?pathname=${encodeURIComponent(pathname)}`, request.nextUrl.origin)
    const res = await fetch(api)
    if (res.ok) {
      const entry = await res.json()
      return NextResponse.redirect(new URL(entry.destination, request.url), entry.permanent ? 308 : 307)
    }
  }
  return NextResponse.next()
}

// fayl: app/api/redirects/route.ts
import redirects from "@/app/redirects/redirects.json"

export function GET(request: Request) {
  const pathname = new URL(request.url).searchParams.get("pathname")
  const entry = pathname ? (redirects as Record<string, unknown>)[pathname] : undefined
  if (!entry) return new Response("No redirect", { status: 400 }) // Bloom filter soxta ijobiysi
  return Response.json(entry)
}

